on", "children": [{"id": "d633cc7e-841a-4556-a75c-b549fb188f79", "type": "concept", "title": "They say/I say moves"}, {"id": "48bb088d-3c50-4f87-a42c-678c8361b4b3", "type": "concept", "title": "Literature mapping"}, {"id": "6ea77d72-22b6-44ba-9031-6579e0614d88", "type": "concept", "title": "Gaps and tensions"}, {"id": "41118d21-ae16-4310-a933-a9f37a9e00a4", "type": "concept", "title": "Contribution statements"}], "description": "Gist: Students learn to position their ideas among existing arguments and voices."}, {"id": "16043b97-338c-4ee1-81eb-4e16a6656f7e", "type": "subtopic", "title": "Research workflow", "children": [{"id": "00832588-9743-4be0-8929-15449582950d", "type": "concept", "title": "Search strategies"}, {"id": "9b52f571-bfc2-45fd-b08d-57d0f10097ec", "type": "concept", "title": "Annotated bibliography"}, {"id": "b66c55a9-bba6-4a2f-b89f-2d2dd59f5e0d", "type": "concept", "title": "Source tracking"}, {"id": "f2de8287-36d9-4eb0-9b29-ff1d7fbcff35", "type": "concept", "title": "Research notes"}], "description": "Gist: A repeatable workflow makes research less chaotic and more intellectually honest."}]}, {"id": "9ecce18e-b959-4ea2-ae06-a028b240e889", "type": "topic", "title": "Evidence, Source Evaluation, and Information Ethics", "description": "Evaluate, integrate, and cite sources responsibly while understanding credibility, bias, context, and intellectual honesty.", "children": [{"id": "f6d36332-42aa-4cd0-b7e4-c33bcc26f6b5", "type": "subtopic", "title": "Evaluating credibility", "children": [{"id": "f868e437-78d6-4fc6-aa11-da2730418862", "type": "concept", "title": "Peer review"}, {"id": "af771876-4f84-4293-a962-52e56fc37ea7", "type": "concept", "title": "Author expertise"}, {"id": "c81175b1-4bfd-4661-a3f9-e200a6fcae2e", "type": "concept", "title": "Publication venue"}, {"id": "7cb75a39-3889-4a11-9597-28ac3ea97645", "type": "concept", "title": "Currency and relevance"}], "description": "Gist: Source evaluation teaches students to judge evidence by context, method, purpose, and authority."}, {"id": "d7e2c751-0698-4c92-bec1-b3b84808c2c8", "type": "subtopic", "title": "Integrating evidence", "children": [{"id": "872afcdc-57e9-429c-ba5a-95e94f4e6e3c", "type": "concept", "title": "Quotation framing"}, {"id": "fa6f75fb-e003-4327-a159-0f7c0b5ed460", "type": "concept", "title": "Paraphrase"}, {"id": "01fbbd90-5e2e-4ddd-8f53-743ba2394cc4", "type": "concept", "title": "Summary"}, {"id": "f82e5e95-71d2-4cd7-af8f-21c09acd98b2", "type": "concept", "title": "Signal phrases"}], "description": "Gist: Evidence works best when introduced, interpreted, and connected to claims."}, {"id": "57c84918-2fbf-44fc-8776-0694fb5eb246", "type": "subtopic", "title": "Citation and ethics", "children": [{"id": "87e85e19-4ef4-44c5-aa5b-e257e605ec80", "type": "concept", "title": "MLA and other styles"}, {"id": "60a0ca01-5c05-43e9-8984-4f29c34cfe50", "type": "concept", "title": "Attribution"}, {"id": "8f5ae74b-0c94-4044-8d8f-bc8eb75f93a6", "type": "concept", "title": "Plagiarism avoidance"}, {"id": "477678c1-d85c-4c03-be68-add913490bb3", "type": "concept", "title": "AI and source transparency"}], "description": "Gist: Responsible citation protects intellectual honesty and clarifies the writer's research trail."}]}, {"id": "9df9c357-6cc5-47bf-b3e3-da47ce22ed50", "type": "topic", "title": "Genre, Conventions, and Discourse Communities", "description": "Study how genres organize expectations and how writers adapt across academic, professional, civic, and digital communities.", "children": [{"id": "7242e5e3-3253-44bd-b1ba-bc60c392529d", "type": "subtopic", "title": "Genre analysis", "children": [{"id": "f6c07984-6888-4580-866f-f03872545a3e", "type": "concept", "title": "Purpose and audience"}, {"id": "1fc4f424-2d31-4ba2-bfc2-0e11f014b420", "type": "concept", "title": "Recurring moves"}, {"id": "a1d55849-b1d3-4145-a328-5d20f9f1b83b", "type": "concept", "title": "Tone and evidence"}, {"id": "14f750ba-665f-4ca0-9046-29936ab4f9cd", "type": "concept", "title": "Layout and citation conventions"}], "description": "Gist: Genres are social actions with recognizable expectations, not just formats."}, {"id": "9d6dbeee-0043-4eec-bb50-c7075aa6b97c", "type": "subtopic", "title": "Discourse communities", "children": [{"id": "7b33e324-07dc-4311-9329-d1167f28d97f", "type": "concept", "title": "Academic disciplines"}, {"id": "d03ac28e-6704-4a5d-8838-4d59599bc5ad", "type": "concept", "title": "Professional communities"}, {"id": "b7797b36-d200-48ec-9171-85b424b13b57", "type": "concept", "title": "Civic publics"}, {"id": "e394ab32-ed23-4982-9a0a-9b1fd801df15", "type": "concept", "title": "Online communities"}], "description": "Gist: Writing changes across communities because values, vocabulary, and evidence standards change."}, {"id": "6eaba041-cfd4-498b-96eb-502bf056872b", "type": "subtopic", "title": "Genre adaptation", "children": [{"id": "ee762f40-c71e-4a06-9c44-11d97587e67e", "type": "concept", "title": "Essay to op-ed"}, {"id": "a925a7f8-0f33-44d8-b0eb-658efed9420f", "type": "concept", "title": "Research paper to brief"}, {"id": "20d662af-673d-401c-8b38-befd11f12101", "type": "concept", "title": "Analysis to presentation"}, {"id": "5e06f6e9-da03-4073-b538-06470af6c8c1", "type": "concept", "title": "Academic to public writing"}], "description": "Gist: Advanced writers transfer ideas across genres while preserving purpose and integrity."}]}, {"id": "2875b9ee-d1ce-44f9-adeb-8f501d3dccf6", "type": "topic", "title": "Style, Grammar, Clarity, and Grace", "description": "Develop sentence-level control for clarity, cohesion, emphasis, rhythm, voice, and reader-centered prose.", "children": [{"id": "3cbc272c-4a8d-4d2d-97af-287dc2e76eeb", "type": "subtopic", "title": "Clarity and cohesion", "children": [{"id": "37a24f00-bc63-46e1-8d6c-64c997c1304a", "type": "concept", "title": "Subjects and verbs"}, {"id": "62662a0b-7fbd-471f-84be-ee0fe962993a", "type": "concept", "title": "Old-to-new information"}, {"id": "2b36a45e-c514-4660-ab5a-c8c0a42b8a27"