ype": "concept", "title": "Revision narrative"}, {"id": "6eec066a-c955-44a9-8d6d-651f9c2ebd93", "type": "concept", "title": "Transfer claims"}, {"id": "0ad22e64-13d7-4b04-a73e-9517dc14a64a", "type": "concept", "title": "Future writing goals"}], "description": "Gist: The reflective introduction turns a collection of assignments into an argument about the writer's development."}]}], "dbBacked": true}$adcrjson$::jsonb,
